def global_modal():
    return '''<div class="overlay" id="global-overlay" hidden aria-hidden="true"><div class="overlay-backdrop" data-close-modal></div><div class="modal-shell" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" aria-label="Close dialog" type="button" data-close-modal>×</button><div id="modal-content"></div></div></div>'''

def page_shell(title,description,current,content,extra_css=''):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f8f7f1"><meta name="description" content="{escape(description)}"><meta name="robots" content="noindex, nofollow"><title>{escape(title)} | Krishna Montessori — Concept</title><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="preconnect" href="https://images.unsplash.com"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="/assets/styles.css">{extra_css}</head><body id="top" data-page="{current.strip('/') or 'home'}"><a href="#main" class="skip-link">Skip to main content</a>{header(current)}<main id="main">{content}</main>{footer()}{global_modal()}<script src="/assets/site.js" defer></script></body></html>'''

def page_hero(label, title, description, image_key=None, image_label='IN THE KRISHNA SPIRIT', extra=''):
    media=f'''<div class="page-hero-media photo-frame">{photo(image_key,'fit-img','(max-width: 700px) 100vw, 650px')}<span class="photo-corner-stamp">{image_label}</span></div>''' if image_key else '<div class="page-hero-doodle"><span>✳</span><span>✦</span><span>◡</span></div>'
    return f'''<section class="page-hero"><div class="container page-hero-grid"><div class="page-hero-copy">{tag(label)}<h1>{title}</h1><p>{description}</p>{extra}</div>{media}</div></section>'''


